 'pages'=>[
 'home'=>['Home','<!-- wp:paragraph --><p>Stillform is a fictional demonstration practice. All projects and editorial texts are demo material.</p><!-- /wp:paragraph -->','A fictional architecture studio demonstration.','','courtyard-house.jpg'],
 'studio'=>['Studio','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">Stillform is an independent, fictional practice working across architecture, interiors and objects. We make calm, tactile places that support ordinary life.</p><!-- /wp:paragraph --><!-- wp:columns {"align":"wide"} --><div class="wp-block-columns alignwide"><!-- wp:column --><div class="wp-block-column"><!-- wp:heading {"level":3} --><h3 class="wp-block-heading">Attention before form</h3><!-- /wp:heading --><p>We begin by recording how a place is used: morning light, daily routes and moments of pause.</p></div><!-- /wp:column --><!-- wp:column --><div class="wp-block-column"><!-- wp:heading {"level":3} --><h3 class="wp-block-heading">Material with purpose</h3><!-- /wp:heading --><p>Stone, timber, lime and metal are chosen for how they age, feel and can be repaired.</p></div><!-- /wp:column --></div><!-- /wp:columns --><!-- wp:quote --><blockquote class="wp-block-quote"><p>The work should feel inevitable, but never anonymous.</p></blockquote><!-- /wp:quote --><!-- wp:heading --><h2 class="wp-block-heading">A small studio, built around dialogue.</h2><!-- /wp:heading --><p>Our fictional team brings together architecture, interior design, furniture and landscape thinking. We keep decisions direct and the project’s central idea visible from first sketch to final fitting.</p>','A small fictional practice built around attention, material and dialogue.','templates/studio.php','studio-table.jpg'],
 'projects'=>['Projects','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">Four fictional studies in climate, material and domestic ritual. Photography is licensed demonstration imagery and does not depict work authored by Stillform.</p><!-- /wp:paragraph -->','Selected fictional architectural studies.','templates/projects.php',''],
