 'projects'=>[
 ['courtyard-house','Courtyard House','A low, inward-looking home organised around water, shade and the movement of the sun.','Residential','2026','Completed','courtyard-house.jpg','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">This fictional courtyard house turns away from the street and opens to planted rooms.</p><!-- /wp:paragraph --><h2 class="wp-block-heading">A room made from weather</h2><p>Four simple wings gather around a shallow pool. Deep reveals temper summer sun while winter light reaches lime-plastered walls.</p>'.$note],
 ['house-of-thresholds','House of Thresholds','A compact renovation using deep openings and built-in furniture to give a modest plan unexpected depth.','Residential','2025','Completed','threshold-house.jpg','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">A fictional renovation where the space between rooms becomes as important as the rooms.</p><!-- /wp:paragraph --><h2 class="wp-block-heading">Living in the thickness</h2><p>Oak-lined thresholds hold shelves, seats and sliding screens, allowing the house to change with the season.</p>'.$note],
 ['ochre-rooms','Ochre Rooms','A guesthouse composed as warm, monolithic rooms around a shared table.','Hospitality','2025','Concept','ochre-rooms.jpg','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">A fictional guesthouse that asks how hospitality can feel elemental and personal.</p><!-- /wp:paragraph --><h2 class="wp-block-heading">Colour as orientation</h2><p>Pigmented plaster shifts from earth red at the public heart to chalk and clay in private rooms.</p>'.$note],
 ['tidal-pavilion','Tidal Pavilion','A seasonal room at the water’s edge, designed to weather with the changing coast.','Cultural','2024','Concept','pavilion.jpg','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">A fictional public room treating tide, wind and salt as collaborators.</p><!-- /wp:paragraph --><h2 class="wp-block-heading">A structure that can yield</h2><p>The pavilion rests on a demountable frame. Every component can be lifted by a small team and repaired with familiar tools.</p>'.$note]],
 'posts'=>[
 ['the-weight-of-a-threshold','The weight of a threshold','A threshold can slow the body, tune the light and prepare us for another kind of room.','stair-light.jpg','2026-09-18 09:00:00','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">The smallest transition in a plan can carry the emotional weight of a whole building.</p><!-- /wp:paragraph --><p>Thresholds are temporal: a shaded porch before bright interior, a low opening before a tall room. Their depth creates places to sit, store and pause.</p><p>This is fictional editorial content created for the Stillform demonstration website.</p>'],
 ['material-not-moodboard','Material is not a moodboard','Fewer materials can make a space richer when each is allowed to age and carry evidence of use.','material-study.jpg','2026-08-27 09:00:00','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">A palette becomes architecture only when materials are asked to do real work.</p><!-- /wp:paragraph --><p>We move from references to samples large enough to hold, scratch and place in changing daylight.</p><p>This is fictional editorial content created for the Stillform demonstration website.</p>'],
 ['drawing-with-daylight','Drawing with daylight','Light is a building material with a schedule. Good rooms anticipate how it moves and disappears.','stone-detail.jpg','2026-07-12 09:00:00','<!-- wp:paragraph {"fontSize":"large"} --><p class="has-large-font-size">Daylight is not simply something a window admits. It is something a room edits.</p><!-- /wp:paragraph --><p>A deep soffit cuts glare; a pale reveal catches light after the sun leaves the glass. The aim is not maximum brightness but useful contrast.</p><p>This is fictional editorial content created for the Stillform demonstration website.</p>']]];
